// Bundled sample artwork (public/samples/*.png, generated by scripts/make-samples.mjs). Always available, so a project
// that uses one only stores its id.
export interface SampleInfo { id: string; title: string; description: string; width: number; height: number }

export const SAMPLES: SampleInfo[] = [
  { id: 'flower', title: 'Flower (radial petals)', description: 'layered radial petal blooms on a violet field', width: 1536, height: 768 },
  { id: 'coral', title: 'Coral (branching fractal)', description: 'recursive branching coral with bright polyp tips', width: 1536, height: 768 },
  { id: 'architecture', title: 'Architecture (perspective lines)', description: 'blueprint-style facades and ground grid converging on vanishing points', width: 1536, height: 768 },
  { id: 'circuit', title: 'Circuit board (traces)', description: 'copper and cyan traces at 45° steps, pads, vias and chips', width: 1536, height: 768 },
  { id: 'cells', title: 'Cells (micrograph-like)', description: 'Voronoi cells with membranes, nuclei and rings in false colour', width: 1536, height: 768 },
  { id: 'marbling', title: 'Marbling (paint in water)', description: 'domain-warped paint bands with dark ink veins', width: 1536, height: 768 },
  { id: 'painting', title: 'Abstract painting (bold shapes)', description: 'overlapping gradient shapes on colour fields', width: 1536, height: 768 },
  { id: 'stripes', title: 'Stripes (geometric)', description: 'high-contrast stripes, zigzags and arcs in bands', width: 1536, height: 768 },
];

export const sampleUrl = (id: string, base = import.meta.env.BASE_URL) => `${base}samples/${id}.png`;
export const sampleThumbUrl = (id: string, base = import.meta.env.BASE_URL) => `${base}samples/thumbs/${id}.png`;
